import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, positionLocal, float, uniform, length, vec2, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ShapeGeometry, ExtrudeGeometry, PlaneGeometry, CylinderGeometry, TorusGeometry, CircleGeometry, DirectionalLight } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const ACCENT = colors.accent ?? '#ff2a38';
  const PAPER = colors.paper ?? '#e8ecf2';
  const BORDER = '#26262f';
  const GRAD0 = (spec.colors?.gradientStops?.[0]?.hex) ?? '#191921';
  const GRAD1 = (spec.colors?.gradientStops?.[1]?.hex) ?? '#121218';

  const root = new Group();
  root.name = 'feature-triptych';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------
  // Backdrop stage plane (7x6 at z=-2.5) with spec gradient + vignette
  // ---------------------------------------------------------------
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial();
  const gradFactor = uv().y.oneMinus(); // at=0 -> top -> GRAD0
  const gradCol = mix(color(GRAD0), color(GRAD1), gradFactor);
  const vig = length(uv().sub(vec2(0.5, 0.5))).mul(0.5).oneMinus().clamp(0.6, 1.0);
  backMat.colorNode = gradCol.mul(vig);
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backGeo, backMat);

  // ---------------------------------------------------------------
  // Node-local rim light (accent-tinted, lower-right, opposite scene key)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(ACCENT, 0.7);
  rim.position.set(3, -2, 2.5);
  root.add(rim);
  const fill = new DirectionalLight('#e8ecf2', 0.35);
  fill.position.set(-2, 3, 4);
  root.add(fill);

  // ---------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------
  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  // Bridged text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const glyphs = items.filter((i) => i.role === 'icon-glyph');
  const titles = items.filter((i) => i.role === 'card-title');
  const bodies = items.filter((i) => i.role === 'body');
  const fallback = [
    { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
  ];

  // ---------------------------------------------------------------
  // Shared card geometry
  // ---------------------------------------------------------------
  const CARD_W = 1.5, CARD_H = 1.9, CARD_R = 0.06, GAP = 0.25;
  const cardShape = roundedRectShape(CARD_W, CARD_H, CARD_R);
  const cardGeo = new ExtrudeGeometry(cardShape, {
    depth: 0.035,
    bevelEnabled: true,
    bevelThickness: 0.008,
    bevelSize: 0.008,
    bevelSegments: 2,
    curveSegments: 10,
  });
  disposables.push(cardGeo);

  // hairline border frame (outer rounded rect with inset hole)
  const borderOuter = roundedRectShape(CARD_W, CARD_H, CARD_R);
  const borderHole = roundedRectShape(CARD_W - 0.012, CARD_H - 0.012, Math.max(0.04, CARD_R - 0.006));
  borderOuter.holes.push(borderHole);
  const borderGeo = new ShapeGeometry(borderOuter, 10);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(BORDER);
  disposables.push(borderGeo, borderMat);

  // disc geometry (machined icon seat)
  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 40);
  const ringGeo = new TorusGeometry(0.205, 0.007, 10, 48);
  disposables.push(discGeo, ringGeo);

  // contact shadow
  const shadowGeo = new CircleGeometry(0.5, 32);
  disposables.push(shadowGeo);

  const cardRecords = [];
  const positionsX = [-(CARD_W + GAP), 0, CARD_W + GAP];

  for (let i = 0; i < 3; i++) {
    const card = new Group();
    card.name = 'feature-card-' + i;
    card.position.set(positionsX[i], 0, 0);
    card.userData.cardIndex = i;

    // card slab — vertical albedo ramp GRAD0 (top) -> GRAD1 (bottom)
    const slabMat = new MeshPhysicalNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      opacity: 0,
    });
    const rampF = positionLocal.y.div(float(CARD_H)).add(0.5).oneMinus().clamp(0, 1);
    slabMat.colorNode = mix(color(GRAD0), color(GRAD1), rampF);
    const slab = new Mesh(cardGeo, slabMat);
    card.add(slab);
    disposables.push(slabMat);

    // hairline border
    const border = new Mesh(borderGeo, borderMat.clone());
    border.material.transparent = true;
    border.material.opacity = 0;
    border.position.z = 0.046;
    card.add(border);
    disposables.push(border.material);

    // machined icon disc
    const discMat = new MeshPhysicalNodeMaterial({
      color: '#1e1e27',
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      transparent: true,
      opacity: 0,
    });
    if ('anisotropy' in discMat) discMat.anisotropy = 0.6;
    const disc = new Mesh(discGeo, discMat);
    disc.rotation.x = Math.PI / 2;
    disc.position.set(0, 0.52, 0.075);
    card.add(disc);
    disposables.push(discMat);

    // emissive accent ring (per-card glow uniform, base 1.6 — the brightest element)
    const glow = uniform(1.6);
    const ringMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
    ringMat.colorNode = color(ACCENT).mul(glow);
    const ring = new Mesh(ringGeo, ringMat);
    ring.position.set(0, 0.52, 0.1);
    card.add(ring);
    disposables.push(ringMat);

    // glyph on disc face
    const glyphText = ctx.fontAtlas.createText(String(glyphs[i]?.text ?? fallback[i].glyph), {
      fontSize: 20,
      color: ACCENT,
      align: 'center',
    });
    glyphText.position.set(0, 0.52, 0.11);
    card.add(glyphText);

    // title
    const titleText = ctx.fontAtlas.createText(String(titles[i]?.text ?? fallback[i].title), {
      fontSize: 20,
      color: PAPER,
      align: 'center',
      maxWidthPx: 132,
    });
    titleText.position.set(0, 0.14, 0.06);
    card.add(titleText);

    // body
    const bodyText = ctx.fontAtlas.createText(String(bodies[i]?.text ?? fallback[i].body), {
      fontSize: 13,
      color: '#b8bec8',
      align: 'center',
      maxWidthPx: 132,
    });
    bodyText.position.set(0, -0.42, 0.06);
    card.add(bodyText);

    // contact shadow under the card
    const shadowOp = uniform(0.5);
    const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    shadowMat.colorNode = color('#000000');
    const radial = length(uv().sub(vec2(0.5, 0.5))).mul(2.0);
    shadowMat.opacityNode = smoothstep(float(1.0), float(0.15), radial).mul(shadowOp);
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(positionsX[i], -1.06, -0.12);
    shadow.scale.set(1.5, 0.28, 1);
    root.add(shadow);
    disposables.push(shadowMat);

    // tag every descendant for raycast hit resolution
    card.traverse((o) => { o.userData.cardIndex = i; });

    root.add(card);
    cardRecords.push({ card, shadow, shadowOp, glow, ring, hovered: false });
  }

  // foreground accent rule (third depth plane, <=10% accent coverage)
  const ruleGeo = new PlaneGeometry(0.9, 0.012);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color(ACCENT).mul(0.9);
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -1.38, 0.35);
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------------------------------------------------------------
  // Entrance: stagger-cards, each card fade-up (opacity 0->1, y +0.2->0)
  // ---------------------------------------------------------------
  cardRecords.forEach((rec, i) => {
    const fadeMats = [];
    rec.card.traverse((o) => {
      if (o.material) { o.material.transparent = true; fadeMats.push(o.material); }
    });
    rec.card.position.y = 0.2;
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(rec.card.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
    const proxy = { o: 0 };
    tl.to(proxy, {
      o: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => { for (const m of fadeMats) m.opacity = proxy.o; },
    }, 0);
    timelines.push(tl);
  });

  // Idle: ONE slow transform — gentle breathing on the accent rule
  const idle = gsap.to(rule.scale, { x: 1.02, duration: 2.6, ease: 'sine.inOut', yoyo: true, repeat: -1 });
  timelines.push(idle);

  // ---------------------------------------------------------------
  // Hover lift states
  // ---------------------------------------------------------------
  function setHover(index, on) {
    const rec = cardRecords[index];
    if (!rec || rec.hovered === on) return;
    rec.hovered = on;
    gsap.to(rec.card.position, { y: on ? 0.06 : 0, z: on ? 0.12 : 0, duration: 0.18, ease: 'power2.out' });
    gsap.to(rec.shadow.scale, { x: on ? 1.85 : 1.5, y: on ? 0.34 : 0.28, duration: 0.18, ease: 'power2.out' });
    gsap.to(rec.shadowOp, { value: on ? 0.34 : 0.5, duration: 0.18, ease: 'power2.out' });
    gsap.to(rec.glow, { value: on ? 2.2 : 1.6, duration: 0.18, ease: 'power2.out' });
  }

  function resolveIndex(ev) {
    let o = ev?.object ?? ev?.target ?? null;
    while (o) {
      if (typeof o.userData?.cardIndex === 'number') return o.userData.cardIndex;
      o = o.parent;
    }
    return -1;
  }

  root.userData.handlers = {
    pointerover: (ev) => { const i = resolveIndex(ev); if (i >= 0) setHover(i, true); },
    pointerout: (ev) => { const i = resolveIndex(ev); if (i >= 0) setHover(i, false); },
    pointermove: (ev) => {
      const i = resolveIndex(ev);
      cardRecords.forEach((_, j) => setHover(j, j === i));
    },
  };

  // ---------------------------------------------------------------
  // Apply configured primitives (none shipped, but honor contract)
  // ---------------------------------------------------------------
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives?.[prim.name];
    if (fn) primHandles.push(fn(root, prim.params ?? {}));
  }

  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(root);
    for (const rec of cardRecords) {
      gsap.killTweensOf(rec.card.position);
      gsap.killTweensOf(rec.shadow.scale);
      gsap.killTweensOf(rec.shadowOp);
      gsap.killTweensOf(rec.glow);
    }
    for (const h of primHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    root.traverse((o) => {
      if (o.geometry?.dispose) o.geometry.dispose();
      if (o.material?.dispose) o.material.dispose();
    });
  };

  return root;
}
